use spore_core::{creature_skin_queue_v1::{Queue,Entry},creature_skin_corner_lookup_v1::corner_hash,creature_skin_cube_walk_v1 as cube,native_sse::Policy};use std::io::Write;
fn main(){let mut out=Vec::new();for case in 0..4{let mut q=if case==3{Queue::from_seed(255,16,64,64).unwrap()}else{Queue::from_seed(0,16,64,64).unwrap()};if case==2{q.entries[0].known=255;let i=(corner_hash(255)&0x3fff)as usize;assert_ne!(i,0);q.keys[i]=255;q.indices[i]=1;q.entries.push(Entry{packed:255,..Entry::default()});}if case==3{let i=(corner_hash(255)&0x3fff)as usize;assert_ne!(i,0);q.keys[i]=255;q.indices[i]=0;q.entries.push(Entry{packed:0,known:255,..Entry::default()});q.cursor=1;}let mut log=Vec::new();q.step(&cube::tables(),&cube::face_records(),[0.;3],1.,0.01,0.001,Policy::Mxcsr1f80,|p|{if log.len()<8{log.push(((p[0] as u32)<<16)|((p[1] as u32)<<8)|p[2] as u32)}if case==1{p[0]-0.6}else{1.}}).unwrap();for x in [q.cursor as u32,q.entries.len() as u32,q.geometry.status]{out.extend(x.to_le_bytes());}for i in 0..16{let e=q.entries.get(i).copied().unwrap_or_default();for x in [e.packed|((e.faces as u32)<<24),e.known as u32|((e.class as u32)<<8)]{out.extend(x.to_le_bytes());}}out.extend((log.len() as u32).to_le_bytes());for i in 0..8{out.extend(log.get(i).copied().unwrap_or(0).to_le_bytes());}for i in 0..0x4000{out.extend(q.keys[i].to_le_bytes());out.extend(q.indices[i].to_le_bytes());}}std::io::stdout().write_all(&out).unwrap();}
